/* ==========================================================================
   cmplt design system — Token contract v2 (Handstyle-aligned)
   --------------------------------------------------------------------------
   Philosophy: No harsh extremes (no #FFFFFF / #000000 poles).
   Primitives: --{scale}-{step}  ·  Semantic: --bg-* / --fg-* / --border-*
   Brand is the same ramp in Light and Dark (no Coral/Jade polarity).
   ========================================================================== */

:root {
  /* ------------------------------------------------------------------------
     TIER 1: PRIMITIVES — Neutral (Hue 85, low chroma)
     ------------------------------------------------------------------------ */
  --neutral-0: oklch(0.992 0.001 85);
  --neutral-25: oklch(0.985 0.002 85);
  --neutral-50: oklch(0.968 0.002 85);
  --neutral-100: oklch(0.950 0.003 85);
  --neutral-200: oklch(0.922 0.003 85);
  --neutral-300: oklch(0.882 0.004 85);
  --neutral-400: oklch(0.745 0.004 85);
  --neutral-500: oklch(0.635 0.004 85);
  --neutral-600: oklch(0.510 0.004 85);
  --neutral-700: oklch(0.360 0.004 85);
  --neutral-750: oklch(0.332 0.003 85);
  --neutral-800: oklch(0.304 0.003 85);
  --neutral-850: oklch(0.286 0.003 85);
  --neutral-900: oklch(0.270 0.003 85);
  --neutral-950: oklch(0.242 0.003 85);

  /* Brand scale (canonical steps used by semantics) */
  --brand-50: oklch(0.962 0.02 35);
  --brand-100: oklch(0.93 0.04 35);
  --brand-200: oklch(0.87 0.075 35);
  --brand-300: oklch(0.78 0.12 35);
  --brand-400: oklch(0.69 0.165 35);
  --brand-500: oklch(0.645 0.175 34);
  --brand-600: oklch(0.585 0.17 34);
  --brand-700: oklch(0.51 0.15 34);
  --brand-800: oklch(0.43 0.12 34);
  --brand-900: oklch(0.35 0.09 34);

  /* Feedback primitives */
  --success-50: oklch(0.955 0.025 162);
  --success-400: oklch(0.58 0.12 162);
  --success-500: oklch(0.515 0.115 162);
  --success-600: oklch(0.465 0.11 162);
  --success-900: oklch(0.28 0.035 162);

  --warning-50: oklch(0.955 0.03 80);
  --warning-400: oklch(0.78 0.15 82);
  --warning-500: oklch(0.76 0.145 80);
  --warning-600: oklch(0.66 0.14 75);
  --warning-900: oklch(0.32 0.015 65);

  --danger-50: oklch(0.955 0.025 22);
  --danger-400: oklch(0.65 0.18 22);
  --danger-500: oklch(0.63 0.18 22);
  --danger-600: oklch(0.55 0.175 22);
  --danger-900: oklch(0.29 0.04 22);

  --info-50: oklch(0.955 0.025 275);
  --info-400: oklch(0.68 0.15 275);
  --info-500: oklch(0.57 0.19 275);
  --info-600: oklch(0.50 0.185 275);
  --info-900: oklch(0.29 0.04 275);

  /* ------------------------------------------------------------------------
     Geometry — radius
     ------------------------------------------------------------------------ */
  --radius-base: 0.5rem;
  --radius-2xs: 0.28125rem;
  --radius-xs: 0.375rem;
  --radius-sm: 0.5rem;
  --radius-md: 0.625rem;
  --radius-squircle: 0.6875rem;
  --radius-panel: 0.875rem;
  --radius-lg: 1.25rem;
  --radius-xl: 1.5rem;
  --radius-full: 9999px;
  --radius-xl-inner-sm: calc(var(--radius-xl) - 0.5rem);
  --radius-xl-inner: calc(var(--radius-xl) - 0.625rem);
  --radius-xl-inner-lg: calc(var(--radius-xl) - 0.75rem);
  --radius-lg-inner-xs: calc(var(--radius-lg) - 0.375rem);
  --radius-lg-inner-sm: calc(var(--radius-lg) - 0.5rem);
  --radius-lg-inner: calc(var(--radius-lg) - 0.625rem);

  /* Layout */
  --container-desktop: 90rem;
  --container-desktop-plus: 108rem;
  --gutter-mobile: 1.25rem;
  --gutter-tablet: 2.5rem;
  --gutter-desktop: 3.5rem;
  --gutter-desktop-plus: 5rem;
  --section-y-mobile: 4.5rem;
  --section-y-tablet: 6.5rem;
  --section-y-desktop: 8.5rem;
  --section-y-desktop-plus: 10.5rem;

  /* Shadow */
  --elevation-none: 0 0 #0000;
  --elevation-xs: 0 1px 2px 0 oklch(0.2 0.005 85 / 0.03);
  --elevation-sm: 0 4px 12px -2px oklch(0.2 0.005 85 / 0.05), 0 1px 3px -1px oklch(0.2 0.005 85 / 0.03);
  --elevation-md: 0 14px 34px -8px oklch(0.18 0.005 85 / 0.08), 0 4px 12px -3px oklch(0.18 0.005 85 / 0.04);
  --elevation-lg: 0 24px 60px -12px oklch(0.18 0.005 85 / 0.12), 0 8px 22px -6px oklch(0.18 0.005 85 / 0.05);
  --elevation-glow: 0 16px 40px -10px oklch(0.645 0.175 34 / 0.18);
  --shadow-none: var(--elevation-none);
  --shadow-xs: var(--elevation-xs);
  --shadow-sm: var(--elevation-sm);
  --shadow-md: var(--elevation-md);
  --shadow-lg: var(--elevation-lg);
  --shadow-glow: var(--elevation-glow);


  /* Motion */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --ease-spring: cubic-bezier(0.175, 0.885, 0.32, 1.1);
  --ease-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
  --duration-instant: 90ms;
  --duration-fast: 150ms;
  --duration-normal: 240ms;
  --duration-slow: 360ms;
  --duration-liquid: 500ms;

  /* Type */
  --type-step--2: 0.75rem;
  --type-step--1: 0.8125rem;
  --type-step-0: clamp(0.9375rem, 0.9148rem + 0.0926vw, 1rem);
  --type-step-1: clamp(1.0625rem, 0.9943rem + 0.2778vw, 1.25rem);
  --type-step-2: clamp(1.25rem, 1.1136rem + 0.5556vw, 1.625rem);
  --type-step-3: clamp(1.5rem, 1.25rem + 1.0185vw, 2.1875rem);
  --type-step-4: clamp(1.875rem, 1.4886rem + 1.5741vw, 2.9375rem);
  --type-step-5: clamp(2.25rem, 1.7045rem + 2.2222vw, 3.75rem);
  --type-step-6: clamp(2rem, 1.0833rem + 4.0741vw, 4.75rem);

  --ui-2xs: 0.6875rem;
  --ui-xs: 0.75rem;
  --ui-sm: 0.8125rem;
  --ui-md: 0.875rem;
  --ui-lg: 0.9375rem;

  --measure-display: 18ch;
  --measure-heading: 28ch;
  --measure-compact: 42ch;
  --measure-lead: 54ch;
  --measure-body: 65ch;

  --leading-display: 1.04;
  --leading-tight: 1.14;
  --leading-snug: 1.28;
  --leading-normal: 1.5;
  --leading-relaxed: 1.65;
  --leading-code: 1.6;

  --tracking-display: -0.035em;
  --tracking-tight: -0.024em;
  --tracking-snug: -0.015em;
  --tracking-normal: -0.005em;
  --tracking-ui: 0em;
  --tracking-wide: 0.025em;
  --tracking-eyebrow: 0.08em;

  --weight-regular: 400;
  --weight-body: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;

  /* ------------------------------------------------------------------------
     TIER 2: SEMANTIC — Light
     ------------------------------------------------------------------------ */
  --bg-canvas: var(--neutral-100);
  --bg-surface: var(--neutral-25);
  --bg-elevated: var(--neutral-0);
  --bg-subtle: var(--neutral-50);
  --bg-muted: var(--neutral-200);

  --bg-brand: var(--brand-500);
  --bg-brand-hover: var(--brand-600);
  --bg-brand-subtle: var(--brand-50);

  --fg-primary: var(--neutral-950);
  --fg-secondary: var(--neutral-600);
  --fg-muted: var(--neutral-500);
  --fg-on-brand: var(--neutral-0);
  --fg-brand: var(--brand-500);

  --border-subtle: var(--neutral-200);
  --border-default: var(--neutral-300);
  --border-strong: var(--neutral-400);
  --border-brand: var(--brand-400);

  --ring-focus: var(--brand-500);

  --status-success: var(--success-500);
  --status-success-bg: var(--success-50);
  --status-warning: var(--warning-600);
  --status-warning-bg: var(--warning-50);
  --status-danger: var(--danger-600);
  --status-danger-bg: var(--danger-50);
  --status-info: var(--info-500);
  --status-info-bg: var(--info-50);

  /* Data series */
  --data-1: var(--brand-500);
  --data-2: var(--success-500);
  --data-3: var(--warning-500);
  --data-4: var(--danger-500);
  --data-5: var(--info-500);

  /* shadcn compatibility (output aliases, never source) */
  --background: var(--bg-canvas);
  --foreground: var(--fg-primary);
  --card: var(--bg-surface);
  --card-foreground: var(--fg-primary);
  --popover: var(--bg-elevated);
  --popover-foreground: var(--fg-primary);
  --primary: var(--bg-brand);
  --primary-foreground: var(--fg-on-brand);
  --secondary: var(--bg-muted);
  --secondary-foreground: var(--fg-primary);
  --muted: var(--bg-muted);
  --muted-foreground: var(--fg-muted);
  --accent: var(--bg-subtle);
  --accent-foreground: var(--fg-primary);
  --destructive: var(--status-danger);
  --border: var(--border-default);
  --input: var(--border-default);
  --ring: var(--ring-focus);
  --chart-1: var(--data-1);
  --chart-2: var(--data-2);
  --chart-3: var(--data-3);
  --chart-4: var(--data-4);
  --chart-5: var(--data-5);
  --sidebar: var(--bg-subtle);
  --sidebar-foreground: var(--fg-primary);
  --sidebar-primary: var(--bg-brand);
  --sidebar-primary-foreground: var(--fg-on-brand);
  --sidebar-accent: var(--bg-muted);
  --sidebar-accent-foreground: var(--fg-primary);
  --sidebar-border: var(--border-subtle);
  --sidebar-ring: var(--ring-focus);
  --radius: var(--radius-md);
}

.dark {
  --weight-body: 380;
  --weight-medium: 485;
  --weight-semibold: 585;
  --weight-bold: 685;

  --bg-canvas: var(--neutral-950);
  --bg-surface: var(--neutral-900);
  --bg-elevated: var(--neutral-800);
  --bg-subtle: var(--neutral-850);
  --bg-muted: var(--neutral-750);

  --bg-brand: var(--brand-500);
  --bg-brand-hover: var(--brand-400);
  --bg-brand-subtle: var(--brand-900);

  --fg-primary: var(--neutral-100);
  --fg-secondary: var(--neutral-400);
  --fg-muted: var(--neutral-500);
  --fg-on-brand: var(--neutral-0);
  --fg-brand: var(--brand-400);

  --border-subtle: var(--neutral-750);
  --border-default: var(--neutral-700);
  --border-strong: var(--neutral-600);
  --border-brand: var(--brand-400);

  --ring-focus: var(--brand-400);

  --status-success: var(--success-400);
  --status-success-bg: var(--success-900);
  --status-warning: var(--warning-400);
  --status-warning-bg: var(--warning-900);
  --status-danger: var(--danger-400);
  --status-danger-bg: var(--danger-900);
  --status-info: var(--info-400);
  --status-info-bg: var(--info-900);

  --data-1: var(--brand-400);
  --data-2: var(--success-400);
  --data-3: var(--warning-400);
  --data-4: var(--danger-400);
  --data-5: var(--info-400);

  --elevation-xs: 0 1px 2px 0 oklch(0 0 0 / 0.18);
  --elevation-sm: 0 4px 12px -2px oklch(0 0 0 / 0.25);
  --elevation-md: 0 16px 36px -8px oklch(0 0 0 / 0.38), 0 4px 12px -4px oklch(0 0 0 / 0.24);
  --elevation-lg: 0 28px 64px -14px oklch(0 0 0 / 0.52), 0 10px 24px -6px oklch(0 0 0 / 0.32);
  --elevation-glow: 0 18px 44px -12px oklch(0.645 0.175 34 / 0.22);
  --shadow-none: var(--elevation-none);
  --shadow-xs: var(--elevation-xs);
  --shadow-sm: var(--elevation-sm);
  --shadow-md: var(--elevation-md);
  --shadow-lg: var(--elevation-lg);
  --shadow-glow: var(--elevation-glow);

}

/* Radius overrides for live customizer */
[data-radius="none"] { --radius-base: 0rem; --radius: 0rem; }
[data-radius="sm"] { --radius-base: 0.375rem; --radius: 0.375rem; }
[data-radius="md"] { --radius-base: 0.5rem; --radius: 0.5rem; }
[data-radius="lg"] { --radius-base: 0.625rem; --radius: 0.625rem; }
[data-radius="xl"] { --radius-base: 0.75rem; --radius: 0.75rem; }

